#include "parse_entry_test_fixture.hpp"
using namespace parse_entry_test;
namespace {
using F=Fixture;
void ordinary_bytes_and_whitespace(){
    for(unsigned byte:{0U,1U,0x20U,0x7fU,0x80U,0xffU}){F f({static_cast<std::uint8_t>(byte)});auto expected=f.document;prefix(expected);f.parse();check(f.document==expected,"ordinary entry changes only initial DWORD counters and one BOM byte");check(f.lower.classified==(byte<0x80?std::vector<std::uint32_t>{byte}:std::vector<std::uint32_t>{}),"all low bytes including NUL reach mandatory classifier; high bit skips classification");if(!byte)f.expect_error();else f.expect_virtual(F::input_address);}
    {F f({' ','\n','\r','\t','x',0});f.lower.classifier=controlled_space;auto expected=f.document;prefix(expected);put(expected,0xa0,2,4);f.parse();f.expect_virtual(F::input_address+4);check(f.document==expected&&f.lower.classified==std::vector<std::uint32_t>{' ','\n','\r','\t','x'},"supplied classification drives whitespace cursor and only LF increments line");}
    {F f({0,0x80});f.lower.classifier=[](auto){return -1;};f.parse();f.expect_virtual(F::input_address+1);check(f.lower.classified==std::vector<std::uint32_t>{0},"nonzero classifier result on NUL advances cursor; no invented NUL guard");}
    {F f({' ',0x80});f.lower.classifier=[&](auto){f.input[0]='\n';put(f.document,0xa0,0xffffffff,4);put(f.document,0x98,0x11112222);return -7;};f.parse();f.expect_virtual(F::input_address+1);check(!word(f.document,0xa0,4)&&word(f.document,0x98)==0x11112222,"LF byte reread/live32increment wraps after callback while cursor keeps cached original buffer");}
    {F f({'\n',0x80});f.lower.classifier=[&](auto){f.input[0]=' ';return 1;};f.parse();f.expect_virtual(F::input_address+1);check(word(f.document,0xa0,4)==1,"classification callback changing LF to non-LF suppresses line increment");}
    {F f;f.lower.classifier=[&](auto){put(f.document,0,F::other_table);f.input[0]=0x80;return 0;};f.parse();f.expect_virtual(F::input_address,F::other_target);check(f.lower.classified==std::vector<std::uint32_t>{'x'},"live table lookup follows classifier mutation and reread of stopped byte");}
}
void bom_short_circuit_and_aliases(){
    struct Case{std::vector<std::uint8_t> input;unsigned advance;bool bom,error;};
    const std::array<Case,6> cases{{{{0xef,0},0,false,false},{{0xef,0xbb,0},0,false,false},{{0xef,0xbb,0xbf,0},3,true,true},{{0xef,0xbb,0xbf,' '},3,true,false},{{0xef,0xbb,0xbf,0x80},3,true,false},{{0xef,0xaa},0,false,false}}};
    for(const auto& c:cases){F f(c.input);f.lower.classifier=[](auto)->std::int32_t{throw std::runtime_error("unexpected second whitespace pass");};auto expected=f.document;prefix(expected,c.bom);f.parse();check(f.document==expected&&f.lower.classified.empty(),"BOM matching preserves exact one-byte flag and performs no post-BOM whitespace classification");if(c.error)f.expect_error();else f.expect_virtual(F::input_address+c.advance);}
    {F f({' ','\n',0xef,0xbb,0xbf,' '});f.lower.classifier=controlled_space;f.parse();f.expect_virtual(F::input_address+5);check(f.lower.classified==std::vector<std::uint32_t>{' ','\n'}&&word(f.document,0xa0,4)==2&&f.document[0x68]==1,"whitespace prefix precedes one BOM pass; following space goes directly to virtual body");}
    {F f({0xef});f.omitted={{F::base+0x68,1}};f.extras.push_back({F::base+0x68,std::span(f.input).first(1)});f.refresh();f.parse();f.expect_error();check(!f.input[0]&&f.lower.classified.empty(),"BOM flag0 store aliases input byte before reread and changes EF to empty-error branch");}
    {F f({0xef,0xbb,0xbf,0});f.omitted={{F::input_address+3,1}};f.extras.push_back({F::input_address+3,std::span(f.document).subspan(0x68,1)});f.refresh();f.parse();f.expect_virtual(F::input_address+3);check(f.document[0x68]==1,"full-BOM flag1 is stored before advanced byte read when they alias");}
    {F f({0x80});put(f.document,0xa0,F::input_address);f.regions={{F::base,std::span(f.document).first(0x98)},{F::base+0x98,std::span(f.document).subspan(0xa0,8)},{F::base+0xa0,std::span(f.document).subspan(0xa0)},{F::input_address,f.input},{F::table_address,f.table}};f.memory.regions=f.regions;f.parse();f.expect_virtual(F::input_address);check(word(f.document,0xa0,4)==1,"buffer is cached before initial line DWORD store changes its aliased pointer backing");}
    {F f({'\n',0x80});constexpr std::uintptr_t wrapped=0xffffffffffffff60ULL;f.regions={{wrapped,std::span(f.document).first(0xa0)},{0,std::span(f.document).subspan(0xa0)},{F::input_address,f.input},{F::table_address,f.table}};f.memory.regions=f.regions;f.lower.classifier=[&](auto){put(f.document,0xa0,0xffffffff,4);return 1;};f.parse(wrapped);f.expect_virtual(F::input_address+1,F::target,wrapped);check(word(f.document,0xa0,4)==0xffffffff,"cached line address0 skips byte reread and live line increment despite LF/nonzero classifier");}
}
void failure_prefixes(){
    for(unsigned at:{0x98U,0xa0U,0x30U,0x68U,0U}){F f;auto expected=f.document;if(at!=0x98&&at!=0xa0)put(expected,0xa0,1,4);if(at!=0x98&&at!=0xa0&&at!=0x30)put(expected,0x30,1,4);if(at==0)expected[0x68]=0;f.omitted={{F::base+at,at==0x68?1U:(at==0x30||at==0xa0?4U:8U)}};f.refresh();unsupported([&]{f.parse();});check(f.document==expected&&f.lower.virtuals.empty()&&f.docs.errors.empty(),"missing cached buffer/counter/BOM/table field preserves exact ordered write prefix");}
    {F f;f.lower.classifier=[](auto)->std::int32_t{throw Failure{77};};auto expected=f.document;put(expected,0xa0,1,4);put(expected,0x30,1,4);failure([&]{f.parse();});check(f.document==expected&&f.lower.classified==std::vector<std::uint32_t>{'x'}&&f.lower.virtuals.empty(),"classifier failure retains two initialized DWORDs but precedes BOM flag store");}
    {F f({'\n',0x80});f.lower.classifier=[&](auto){f.omitted={{F::input_address,1}};f.refresh();return 1;};auto expected=f.document;put(expected,0xa0,1,4);put(expected,0x30,1,4);unsupported([&]{f.parse();});check(f.document==expected,"missing post-classifier LF reread fails before line increment,cursor advance and BOM store");}
    for(std::vector<std::uint8_t> bytes:std::array<std::vector<std::uint8_t>,3>{{{0xef},{0xef,0xbb},{0xef,0xbb,0xbf}}}){F f(bytes);auto expected=f.document;prefix(expected,bytes.size()==3);unsupported([&]{f.parse();});check(f.document==expected&&f.lower.classified.empty()&&f.lower.virtuals.empty(),"incomplete BOM1/2/advanced byte mapping preserves short-circuit read and flag-store prefix");}
    {F f;f.omitted={{F::table_address+0x80,8}};f.refresh();auto expected=f.document;prefix(expected);unsupported([&]{f.parse();});check(f.document==expected&&f.lower.virtuals.empty(),"unknown missing controlled virtual slot fails after initialization/BOM prefix");}
    {F f;f.extras.push_back({F::table_address+0x80,std::span(f.alternate).first(8)});f.refresh();auto expected=f.document;prefix(expected);unsupported([&]{f.parse();});check(f.document==expected&&f.lower.virtuals.empty(),"ambiguous controlled virtual slot fails without calling any image pointer");}
    {F f({0xef,0xbb,0xbf,'x'});f.lower.virtual_hook=[&](const auto&){put(f.document,0xa0,99,4);throw Failure{77};};failure([&]{f.parse();});check(f.document[0x68]==1&&word(f.document,0xa0,4)==99&&f.lower.virtuals.size()==1&&f.docs.errors.empty(),"virtual-effect failure retains complete BOM and supplied effect mutation without rollback");}
    {F f({0});f.docs.error_hook=[](const auto&){throw Failure{77};};auto expected=f.document;prefix(expected);failure([&]{f.parse();});check(f.document==expected&&f.docs.errors.size()==1&&f.lower.classified==std::vector<std::uint32_t>{0},"error-provider failure retains initialized prefix after mandatory NUL classification");}
}
}
int main(){try{ordinary_bytes_and_whitespace();bom_short_circuit_and_aliases();failure_prefixes();std::cout<<"PASS: "<<checks<<" parse-entry core checks; mandatory byte classification,cached cursor/live line wrap,short-circuit BOM/aliases,wrapped zero line address,live virtual identity and failure prefixes; classifier/error/virtual bodies supplied\n";}catch(const std::exception& e){std::cerr<<"FAIL after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}catch(...){std::cerr<<"FAIL: unexpected failure after "<<checks<<" checks\n";return 1;}}
